			DegisiklikVar = false;
		}
		else
		{
			MessageBox.Show("Ayarlar kayıt edilemedi!", "İşlem başarısız", MessageBoxButtons.OK);
		}
	}

	private void AktarimKriterSablonlariOlustur()
	{
		KriterListesi.Items.Clear();
		foreach (string item in GenelEvrakKriterParametreleri.GetKriterAdlari(_mikrouygulamabilgileri.baglantibilgileri, _mikrouygulamabilgileri.MikroFirmaDBName))
		{
			KriterListesi.Items.Add(item);
		}
	}

	private void lb_kullanicilar_SelectedValueChanged(object sender, EventArgs e)
	{
		if (lb_sablonlar.SelectedValue == null)
		{
			return;
		}
		bool flag = true;
		if (DegisiklikVar && AktifKullanici != lb_sablonlar.SelectedValue.ToString())
		{
			switch (MessageBox.Show("Kayıt edilmemiş değişiklikler var kaydetmek istiyor musunuz?", "Onaylama", MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question))
			{
			case DialogResult.Yes:
				KullaniciParametreKaydet();
				flag = true;
				break;
			case DialogResult.No:
				flag = true;
				break;
			case DialogResult.Cancel:
				flag = false;
				break;
			}
		}
		if (AktifKullanici == lb_sablonlar.SelectedValue.ToString())
		{
			flag = false;
		}
		if (flag)
		{
			tc_ayarlar.Enabled = true;
			AktifKullanici = lb_sablonlar.SelectedValue.ToString();
			_aktarimparametreleri = ParametrelerDefault.GenelAktarimTxtCsvSablon(AktifKullanici);
			ParametreData.ParametreOku(_mikrouygulamabilgileri.baglantibilgileri, _mikrouygulamabilgileri.MikroFirmaDBName, _aktarimparametreleri, "GenelAktarim", "", "TxtCsvAktarimSablon", AktifKullanici);
			EkranBilgiGuncelle();
			DegisiklikVar = false;
		}
		else
		{
			lb_sablonlar.SelectedItem = AktifKullanici;
		}
	}

